class Solution {
    public int countTriples(int n) {
        int limit = n * n;
        boolean[] isSquare = new boolean[limit + 1];

        for (int c = 1; c <= n; c++) {
            isSquare[c * c] = true;
        }

        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int sum = a * a + b * b;
                if (sum > limit) {
                    break;
                }
                if (isSquare[sum]) {
                    count++;
                }
            }
        }

        return count;
    }
}

